// spec: specs/premium-store.md (раздел 4.1)
// seed: tests/seed.new03.spec.ts
// РАСХОЖДЕНИЯ со спекой (сверено с живой страницей 19.11.2026):
// - Вход: тест открывает /subscription напрямую (путь «/settings → Magnet Premium» не проходился).
// - Спека: роль new03 → new03-r12.json; по заданию раунда 13 используется свежий new03-r13.json.
// - У new03 автопродление ВЫКЛ: «החידוש בוטל · Premium פעיל עד 20.01.2027», строка тумблера «כבוי · המנוי יסתיים ב-20.01.2027» — проверяется как есть, тумблер и «החלפת מסלול» не нажимаются.
// - «מה כולל Premium» — кнопка (button), а не просто текст.
// - Шаблон остатка суперлайков: «נשארו N מתוך 50 סופר לייק»; бустов и возвратов — без «נשארו»: «N מתוך 2 בוסטים», «N מתוך 30 חזרות לאחור».
// - «רכישות» содержит и строки со статусом «נכשל» (не только «שולם»); проверяется ≥1 «שולם» с «₪».
import { test, expect } from '@playwright/test';
import path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/new03-r13.json'), colorScheme: 'dark' });

test.describe('Раунд 13: «המנוי שלי» (#05baf0 #e5e14a)', () => {
  test('המנוי שלי у Premium: «פעיל», «ניהול המנוי», «מתוך 50/2/30», «רכישות» @iphone @prod-safe', async ({ page }) => {
    // 1. /settings → «Magnet Premium» (или /subscription).
    await page.goto('/subscription');
    await expect(page.getByText('המנוי שלי', { exact: true })).toBeVisible();

    // 2. Посмотреть экран до низа. Тумблер и «החלפת מסלול» не трогать.
    await expect(page.getByText('Magnet Premium', { exact: true })).toBeVisible();
    await expect(page.getByText('פעיל', { exact: true })).toBeVisible();
    await expect(page.getByText(/החידוש בוטל · Premium פעיל עד 20\.01\.2027/)).toBeVisible();
    await expect(page.getByRole('button', { name: 'מה כולל Premium' })).toBeVisible();

    await expect(page.getByText('ניהול המנוי', { exact: true })).toBeVisible();
    await expect(page.getByText('חידוש אוטומטי', { exact: true })).toBeVisible();
    await expect(page.getByRole('switch', { name: 'חידוש אוטומטי' })).toBeVisible();
    await expect(page.getByText(/כבוי · המנוי יסתיים ב-20\.01\.2027/)).toBeVisible();
    await expect(page.getByRole('button', { name: /החלפת מסלול/ })).toBeVisible();

    await expect(page.getByText('נשאר החודש', { exact: true })).toBeVisible();
    await expect(page.getByText(/^נשארו \d+ מתוך 50 סופר לייק$/)).toBeVisible();
    await expect(page.getByText(/^\d+ מתוך 2 בוסטים$/)).toBeVisible();
    await expect(page.getByText(/^\d+ מתוך 30 חזרות לאחור$/)).toBeVisible();

    const purchasesTitle = page.getByText('רכישות', { exact: true });
    await purchasesTitle.scrollIntoViewIfNeeded();
    await expect(purchasesTitle).toBeVisible();
    const paidRow = page.getByText('שולם', { exact: true }).first();
    await expect(paidRow).toBeVisible();
    await expect(page.getByText(/₪\d+\.\d{2}/).first()).toBeVisible();
    await expect(page.getByText('אפשר לבטל בכל עת')).toHaveCount(0);
  });
});
